def glyph(name, tone=''):
    """A glyph from the set, 16px, in the text's colour or a tone: blue, teal, purple, yellow, green or red. An
    unknown name draws globe.

        glyph('task', 'blue')
    """
    name = name if name in GLYPHS else 'globe'
    cls = f'glyph glyph--{e(tone)}' if tone else 'glyph'
    return f'<svg class="{cls}" width="16" height="16" aria-hidden="true"><use href="#g-{name}"/></svg>'


def symbols(body):
    """The sprite symbols for the glyphs the body uses.

        symbols('<use href="#g-task"/>')
    """
    used = set(re.findall(r'href="#g-([\w-]+)"', body))
    return ''.join(f'<symbol id="g-{k}" viewBox="0 0 16 16">{v}</symbol>' for k, v in GLYPHS.items() if k in used)
